-- Production migration: 20260905204402_contract_acquisition_lifecycle_20260905
-- This file records the contract acquisition lifecycle applied to production.
-- Contract lifecycle: opportunity -> qualification -> pursuit -> solicitation -> proposal -> submission gate -> award -> contract -> performance.
-- Contract records are staff-controlled; buyer portal access is read-only and organization-scoped.
create table if not exists public.dd_contract_opportunities (id uuid primary key default gen_random_uuid(), public_reference text not null unique default ('DD-OPP-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), source_system text not null default 'INTERNAL', source_url text, external_opportunity_id text, title text not null, buyer_name text, buyer_type text, buyer_organization_id uuid references public.dd_client_organizations(id), procurement_path text not null default 'OTHER', solicitation_type text, solicitation_number text, naics_code text, psc_code text, jurisdiction_code text not null default 'GA', place_of_performance text, posted_at timestamptz, response_deadline timestamptz, estimated_value numeric, contract_ceiling numeric, term_summary text, set_aside text, source_authority text, evidence_status text not null default 'UNVERIFIED', fit_status text not null default 'UNASSESSED', stage text not null default 'RESEARCH', bid_no_bid text not null default 'PENDING', priority text not null default 'NORMAL', research_notes text, qualification_notes text, metadata jsonb not null default '{}'::jsonb, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
