create or replace function public.dd_contract_staff_access() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((auth.jwt()->'app_metadata'->>'role') in ('owner','admin','staff_admin','staff'),false) or exists (select 1 from public.dd_portal_identities p where p.auth_user_id=auth.uid() and p.is_active and p.portal_role in ('staff_admin','owner')); $$;
revoke all on function public.dd_contract_staff_access() from public; grant execute on function public.dd_contract_staff_access() to authenticated;
