create policy dd_contracts_customer_read on public.dd_contracts for select to authenticated using (buyer_organization_id is not null and exists (select 1 from public.dd_portal_identities p where p.auth_user_id=auth.uid() and p.is_active and p.organization_id=dd_contracts.buyer_organization_id and p.portal_role in ('property_manager','procurement','customer')));
create policy dd_contract_events_customer_read on public.dd_contract_events for select to authenticated using (contract_id is not null and exists (select 1 from public.dd_contracts c join public.dd_portal_identities p on p.organization_id=c.buyer_organization_id where c.id=dd_contract_events.contract_id and p.auth_user_id=auth.uid() and p.is_active and p.portal_role in ('property_manager','procurement','customer')));
create or replace function public.dd_contract_touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;

